{
    trade: `<circle cx="90" cy="86" r="44" fill="#6C5DD3" opacity=".85"/><circle cx="150" cy="86" r="44" fill="#F5A01F" opacity=".85"/>
      ${Array.from({ length: 12 }, (_, i) => { const a = i * Math.PI / 6; return `<circle cx="${150 + 30 * Math.cos(a)}" cy="${86 + 30 * Math.sin(a)}" r="2.6" fill="#FFE07A"/>`; }).join('')}
      <path d="M90 86 m-22 0 a22 22 0 1 0 44 0 a22 22 0 1 0 -44 0" fill="none" stroke="#fff" stroke-width="1.5" opacity=".7"/>
      <g stroke="#fff" stroke-width="1" opacity=".6">${Array.from({ length: 24 }, (_, i) => { const a = i * Math.PI / 12; return `<path d="M${90 + 16 * Math.cos(a)} ${86 + 16 * Math.sin(a)} L${90 + 22 * Math.cos(a)} ${86 + 22 * Math.sin(a)}"/>`; }).join('')}</g>
      <path d="M20 160 H220" stroke="#25272D" stroke-width="1"/><rect x="40" y="140" width="40" height="20" fill="#25272D"/><rect x="84" y="146" width="30" height="14" fill="#1667B0"/><rect x="118" y="142" width="36" height="18" fill="#3B5BCC"/><rect x="158" y="148" width="26" height="12" fill="#E8890C"/>`,
    econ: `<path d="M30 150 H210" stroke="#25272D"/>${[40, 62, 54, 78, 70, 92, 100].map((h, i) => `<rect x="${40 + i * 24}" y="${150 - h}" width="14" height="${h}" fill="${i === 6 ? '#1B8AD3' : '#3B5BCC'}" opacity="${i === 6 ? 1 : .55}"/>`).join('')}
      <text x="190" y="52" font-family="'Inter Tight',Inter,sans-serif" font-size="46" fill="#25272D" text-anchor="middle">₹</text><path d="M44 108 L68 90 L92 96 L116 72 L140 80 L164 56 L188 50" stroke="#B23B2E" stroke-width="2" fill="none"/>`,
    court: `<path d="M50 70 L120 36 L190 70Z" fill="#1667B0"/><rect x="50" y="70" width="140" height="8" fill="#25272D"/>${[62, 88, 114, 140, 166].map(x => `<rect x="${x}" y="80" width="12" height="62" fill="#FFFFFF" stroke="#1667B0"/>`).join('')}<rect x="44" y="142" width="152" height="8" fill="#25272D"/><rect x="36" y="150" width="168" height="8" fill="#1667B0"/><circle cx="120" cy="56" r="6" fill="#FFD27A"/>`,
    mineral: `${[[80, 90, 30, '#3B5BCC'], [130, 70, 24, '#0A97B8'], [160, 120, 34, '#6C5DD3'], [100, 140, 20, '#E8890C']].map(([x, y, r, c]) => `<path d="M${x} ${y - r} L${x + r * .87} ${y - r / 2} L${x + r * .87} ${y + r / 2} L${x} ${y + r} L${x - r * .87} ${y + r / 2} L${x - r * .87} ${y - r / 2}Z" fill="${c}" opacity=".85"/>`).join('')}`,
    leaf: `<path d="M60 150 C60 80 120 40 190 40 C190 110 140 160 60 150Z" fill="#3E9A55"/><path d="M60 150 C100 110 140 80 180 50" stroke="#E8F3FC" stroke-width="2" fill="none"/><path d="M20 160 C60 150 90 170 130 160 S200 150 230 160" stroke="#0A97B8" stroke-width="3" fill="none"/>`,
    orbit: `<ellipse cx="120" cy="96" rx="90" ry="34" fill="none" stroke="#25272D" stroke-dasharray="3 5"/><circle cx="120" cy="96" r="30" fill="#0A97B8"/><path d="M96 86 Q120 70 146 90" stroke="#E8F3FC" stroke-width="2" fill="none"/><g transform="translate(196 78) rotate(30)"><path d="M0 -14 L6 0 V14 H-6 V0Z" fill="#FFFFFF" stroke="#25272D"/><path d="M-2 14 L0 22 L2 14" fill="#F5A01F"/></g>`,
  }

{
    title: c.t,
    html: `<div class="pg-hero"><span class="tag" style="color:${sj.c}"><span class="sw"></span>${sj.n}</span><h1 style="margin-top:8px">${c.t}</h1><p>${c.l} lectures · ${c.p}% complete · Last: ${c.last}</p>
      <div class="nu-prog" style="margin-top:14px"><div class="track"><i style="width:${c.p}%"></i></div><span>${c.p}%</span></div>
      <button class="btn btn-ink btn-sm" style="margin-top:16px" data-act="toast:Resuming ${c.last}">${ic('play')}Resume</button></div>
      <div class="sec">${Array.from({ length: 8 }, (_, i) => { const n = i + 1, d = n / 8 * 100 <= c.p; return `<div class="lec ${d ? 'dn' : ''}" data-act="toast:Lecture ${n} would open here"><span class="n">${d ? ic('check') : n}</span><div><b>Lecture ${n}</b><small>${40 + (i * 7) % 25} min</small></div>${ic('chev')}</div>`; }).join('')}</div>` }

{
    title: 'Courses & Lectures',
    html: `<div class="pg-hero"><h1>Courses &amp; Lectures</h1><p>Every GS subject, CSAT, optional and answer writing — organised by the syllabus.</p></div>
      <div class="chips" style="margin-bottom:8px">${['All', 'GS I', 'GS II', 'GS III', 'GS IV', 'CSAT', 'Optional'].map((x, i) => `<button class="chip ${i ? '' : 'on'}" data-act="chipOne">${x}</button>`).join('')}</div>
      <div class="course-list">${[...COURSES.map(c => ({ s: c.s, t: c.t, m: c.l + ' lectures · ' + c.p + '%', id: c.id })), ...MORE_COURSES].map(c => `<div class="crs" data-act="${c.id ? (c.id === 'c1' ? 'push:lesson' : 'push:course:' + c.id) : 'toast:Course preview would open here'}"><span class="sp" style="--c:${SUBJ[c.s].c}"></span><div><h4>${c.t}</h4><p>${c.m}</p></div>${ic('chev')}</div>`).join('')}</div>`,
  }

{
    title: 'Notes tracker',
    html: `<div class="pg-hero"><h1>Notes tracker</h1><p>48 notes in October across 19 days. Economy and Environment need attention.</p></div>
      <div class="sec">${COVER.map(c => { const n = { polity: 18, history: 11, geo: 9, eco: 6, env: 4 }[c.k]; return `<div class="rb" style="grid-template-columns:96px 1fr 40px"><b>${SUBJ[c.k].n}</b><div class="tr"><i style="width:${n / 18 * 100}%;background:${SUBJ[c.k].c}"></i></div><span>${n}</span></div>`; }).join('')}
      <div class="eyebrow" style="margin:22px 0 8px">Topics with lectures but no notes</div>
      ${['Monetary policy transmission', 'Biodiversity hotspots', 'Federalism: Inter-state councils', 'Carnatic wars', 'Ocean currents', 'Money bills vs finance bills'].map(t => `<div class="slot"><span class="tm">${ic('pen')}</span><div class="bx" style="--c:var(--history)"><b>${t}</b><small>Lecture watched · notes pending</small></div></div>`).join('')}</div>`,
  }

{
    title: 'Test Series',
    html: `<div class="pg-hero"><h1>Test Series</h1><p>Scheduled sectional and full-length tests. Each opens as a timed quiz.</p></div>
      <div class="sec"><div class="eyebrow" style="margin-bottom:4px">Upcoming</div>${TESTS.map(x => `<div class="tsi" data-act="testStart"><div class="dt"><b>${x.d}</b><span>${x.m}</span></div><div><h5>${x.t}</h5><p>${x.s}</p></div><span class="st">${x.st}</span></div>`).join('')}
      <div class="eyebrow" style="margin:22px 0 4px">Completed</div>${[['18', 'Oct', 'Prelims Test 11 · Modern History', '68 / 100'], ['11', 'Oct', 'Full-Length Mock 3', '94 / 200'], ['4', 'Oct', 'Prelims Test 10 · Economy', '58 / 100']].map(x => `<div class="tsi" data-act="push:history"><div class="dt"><b>${x[0]}</b><span>${x[1]}</span></div><div><h5>${x[2]}</h5><p>Score ${x[3]}</p></div>${ic('chev')}</div>`).join('')}</div>`,
  }

{
    title: 'Quiz history',
    html: `<div class="pg-hero"><h1>71% <span style="color:var(--muted);font-size:18px">avg. accuracy</span></h1><p>Up 9 points in 30 days. Writs and Economy still pull the average down.</p></div>
      <div class="sec"><svg viewBox="0 0 340 170" style="width:100%"><g stroke="var(--rule)">${[50, 90, 130].map(y => `<path d="M10 ${y}H330"/>`).join('')}</g><polyline points="${pts}" fill="none" stroke="var(--brand)" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>${h.map((v, i) => `<circle cx="${20 + i * 48}" cy="${150 - (v - 40) * 3.2}" r="4" fill="var(--paper)" stroke="var(--brand)" stroke-width="2"/><text x="${20 + i * 48}" y="${140 - (v - 40) * 3.2}" text-anchor="middle" font-size="10" fill="var(--ink-2)" font-family="Inter">${v}</text>`).join('')}<text x="10" y="166" font-size="10" fill="var(--muted)" font-family="Inter">Sep</text><text x="330" y="166" text-anchor="end" font-size="10" fill="var(--muted)" font-family="Inter">Today</text></svg>
      ${[['Polity · Writs', '8/10', '20 Oct'], ['Prelims Test 11 · Modern History', '68/100', '18 Oct'], ['Economy · Inflation', '6/10', '16 Oct'], ['Environment · Wetlands', '7/10', '14 Oct'], ['Full-Length Mock 3', '94/200', '11 Oct']].map(x => `<div class="slot"><span class="tm">${x[2]}</span><div class="bx" style="--c:var(--brand);display:flex;justify-content:space-between"><b>${x[0]}</b><small style="font-weight:600;color:var(--ink)">${x[1]}</small></div></div>`).join('')}</div>`,
  }

{
    title: 'Mains Answer Bank',
    html: `<div class="pg-hero"><h1>Mains Answer Bank</h1><p>Previous-year and expected questions with model answers and approach notes.</p></div>
      <div class="chips" style="margin-bottom:6px">${['All', 'GS I', 'GS II', 'GS III', 'GS IV', 'Essay'].map((x, i) => `<button class="chip ${i ? '' : 'on'}" data-act="chipOne">${x}</button>`).join('')}</div>
      <div class="sec">${ANSWERBANK.map(q => `<div class="clip" style="grid-template-columns:1fr" data-act="push:answer:${q.id}"><div><span class="src">${q.p} · ${q.m} marks · ${q.w} words</span><h4>${q.t}</h4></div></div>`).join('')}</div>`,
  }

{
    title: 'Past evaluations',
    html: `<div class="pg-hero"><h1>8.1 <span style="font-size:18px;color:var(--muted)">/ 15 average</span></h1><p>12 answers evaluated. Structure has improved; content depth is the next lever.</p></div>
      <div class="sec">${PASTEVALS.map((e, i) => `<div class="pe" style="border-color:var(--rule)" data-act="${i === 0 ? 'push:mainsResult' : 'toast:Evaluation report would open here'}"><span class="sc" style="border-color:var(--rule-2)">${e.s}<small>/${e.of}</small></span><div><b>${e.t}</b><span style="color:var(--muted);opacity:1">${e.p} · ${e.d}</span></div>${ic('chev')}</div>`).join('')}</div>`,
  }

{
    title: sj.n + ' · Question bank',
    html: `<div class="pg-hero"><span class="tag" style="color:${sj.c}"><span class="sw"></span>Unlimited Question Bank</span><h1 style="margin-top:8px">${sj.n}</h1><p>Practise by topic. Accuracy is from your last 30 days.</p></div>
      <div class="sec">${topics.map((t, i) => { const acc = [48, 62, 71, 52, 66, 80][i] || 60; return `<div class="rb" style="grid-template-columns:1fr 70px 36px;cursor:pointer" data-act="quiz"><b>${t}<small style="display:block;font-weight:400;color:var(--muted);font-size:11.5px">${180 + i * 74} questions</small></b><div class="tr"><i style="width:${acc}%;background:${acc < 55 ? 'var(--bad)' : sj.c}"></i></div><span>${acc}%</span></div>`; }).join('')}
      <button class="btn btn-ink btn-wide" style="margin-top:20px" data-act="quiz">Start 10 mixed questions ${ic('arrow')}</button></div>`,
  }

{ title: 'System status', html: `<div class="me-page ss">
    <section class="ss-orb"><span class="ss-w"></span><span class="ss-w d2"></span><div class="ss-core"><svg viewBox="0 0 64 32" aria-hidden="true"><path d="M2 16h14l5-11 9 22 6-14 4 3h22" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg></div></section>
    <h2 class="ss-t">All systems operational</h2><p class="ss-s">Every PrepAssist service is responding · checked <b class="ss-ago">just now</b></p>
    <div class="ss-tiles">
      <div class="ss-tile"><small>${ic('bolt')}Latency</small><b><span class="ss-lat">42</span><em>ms</em></b><div class="ss-spark">${Array.from({ length: 16 }, () => '<i></i>').join('')}</div></div>
      <div class="ss-tile"><small>${ic('chart')}Uptime · 90 days</small><b>99.99<em>%</em></b><div class="ss-days">${Array.from({ length: 45 }, (_, i) => `<i class="${i === 31 ? 'a' : ''}"></i>`).join('')}</div></div>
    </div>
    <section class="ss-list"><h6>Live handshakes</h6>${[['lock', 'Authentication', 'Firebase Auth handshake', 'Verified'], ['refresh', 'Realtime sync', 'Firestore connection', 'Connected'], ['spark', 'Generative engine', 'AI evaluation core', 'Standby'], ['cloud', 'Cloud Vault', 'Encrypted file storage', 'Reachable'], ['phone', 'Native bridge', 'App runtime', 'Initialised']].map(h => `<div class="ss-h"><span class="ss-hi">${ic(h[0])}</span><div><b>${h[1]}</b><small>${h[2]}</small></div><em><i class="ss-sp"></i><span>${ic('check')}${h[3]}</span></em></div>`).join('')}</section>
    <button class="ss-re" data-act="ssRerun">${ic('refresh')}Run diagnostics again</button>
  </div>`, mount: el => {
    el.querySelectorAll('.ss-h').forEach((h, i) => setTimeout(() => h.classList.add('ok'), 500 + i * 420));
    const lat = el.querySelector('.ss-lat'), bars = [...el.querySelectorAll('.ss-spark i')], hist = Array.from({ length: 16 }, () => 34 + Math.random() * 18);
    const draw = () => bars.forEach((b, i) => { b.style.height = (hist[i] - 20) * 2.2 + '%'; });
    draw(); let n = 0;
    const t = setInterval(() => { if (!document.body.contains(el)) return clearInterval(t); const v = Math.round(36 + Math.random() * 14); hist.shift(); hist.push(v); lat.textContent = v; draw(); n++; el.querySelector('.ss-ago').textContent = n < 2 ? 'just now' : n + 's ago'; }, 1100);
  } }

{
    pqb: `${S.pqb.done} solved`, testquiz: `${S.tq.lib.length} in library`, answerbank: `${ANSWERBANK.length} questions`, mains: '20 credits',
    current: `${caPool(isoD(TODAY)).length} today`, notesys: `${NOTESYS.length} compendiums`, syllabus: `${Math.round(all.filter(x => x.a).length / all.length * 100)}% started`,
    saved: `${S.saved.size + S.savedLinks.length} saved`, upload: 'PDF · DOCX · JPG', cloud: `${vaultMB().toFixed(1)} MB used`, tracker: `${NOTES.length} notes`,
    querydb: '4 credits', mindmaps: `${S.maps.length} saved`,
  }

{ title: 'Test Series to Quiz', html: `<div class="me-page tlp">
    ${tHero('testquiz', 'Any test PDF, <em>a live mock</em>', '100-question UPSC mocks with instant, free re-attempts.', tStat(T.lib.length, 'in library') + tStat(T.lib.reduce((a, b) => a + b.att, 0), 'attempts') + tStat('Free', 're-attempts'))}
    <div class="sg2" role="tablist"><button class="${T.tab === 'new' ? 'on' : ''}" data-act="tqTab:new">${ic('upload')}Upload new</button><button class="${T.tab === 'lib' ? 'on' : ''}" data-act="tqTab:lib">${ic('learn')}My test series</button></div>
    ${T.tab === 'new' ? `
      <h6 class="tl-k">PDF document</h6>
      ${T.file ? `<div class="tq-file"><span class="tq-pdf">PDF</span><div><b>${T.file.n}</b><small>${T.file.pg} pages · ${T.file.sz}</small></div><button class="tq-x" data-act="tqClear" aria-label="Remove">${ic('close')}</button></div>`
        : `<button class="tl-drop" data-act="tqPick"><span>${ic('upload')}</span><b>Tap to upload a PDF</b><small>Test series papers · question banks · mock booklets</small></button>`}
      <h6 class="tl-k">Language version</h6>
      <div class="sg2 sm"><button class="${T.lang === 'en' ? 'on' : ''}" data-act="tqLang:en">${ic('globe')}English</button><button class="${T.lang === 'hi' ? 'on' : ''}" data-act="tqLang:hi">${ic('language')}हिन्दी</button></div>
      <section class="tq-tips"><h6>Tips for best results</h6><ol><li>Use text-based PDFs — scanned images or camera photos won’t work.</li><li>Digital question banks and printed booklets are both supported.</li><li>Bilingual papers are split automatically using the language you pick.</li><li>Finished conversions are saved to your library for free re-attempts.</li></ol></section>
      <div id="tqBusy"></div>
      <button class="tl-cta ${T.file ? '' : 'off'}" data-act="tqGo" ${T.file ? '' : 'disabled'}>${ic('bolt')}${T.file ? 'Convert to quiz' : 'Select a PDF first'}</button>`
    : `${T.lib.map((x, i) => `<article class="tq-card"><div class="tq-ct"><span class="tq-sc"><svg viewBox="0 0 48 48">${ring(19, x.best / x.q, 5, '#1B8AD3', '#EEF2F7')}</svg><b>${Math.round(x.best / x.q * 100)}%</b></span><div><b>${x.t}</b><small>${x.q} questions · ${x.lang} · added ${x.d}</small></div></div>
        <div class="tq-cf"><span>${ic('history')}${x.att ? `${x.att} attempt${x.att > 1 ? 's' : ''} · best ${x.best}/${x.q}` : 'New · not attempted yet'}</span><button data-act="tqStart:${i}">${x.att ? ic('refresh') + 'Re-attempt' : ic('play') + 'Start mock'}</button></div></article>`).join('')}
      <button class="tl-ghost" data-act="tqTab:new">${ic('plus')}Convert another PDF</button>`}
  </div>` }

{ title: 'Mains Answer Bank', html: `<div class="me-page tlp">
    ${tHero('answerbank', 'Model answers, <em>decoded</em>', 'Study examiner-ready frameworks, then write your own and get it evaluated.', tStat(ANSWERBANK.length, 'questions') + tStat('GS I–IV', 'papers') + tStat('EN · हिं', 'languages'))}
    <div class="cx-fbar ab"><div class="cx-seg" style="grid-template-columns:repeat(2,1fr)"><button class="${B.lang === 'en' ? 'on' : ''}" data-act="abLang:en">English</button><button class="${B.lang === 'hi' ? 'on' : ''}" data-act="abLang:hi">हिन्दी</button></div></div>
    <div class="ch2">${['All', 'GS I', 'GS II', 'GS III', 'GS IV'].map(p => `<button class="${B.p === p ? 'on' : ''}" data-act="abP:${p}">${p === 'All' ? 'All papers' : p}</button>`).join('')}</div>
    ${list.map(q => { const M = AB_META[q.id] || { topic: q.p, c: '#1B8AD3' }, open = B.open[q.id]; return `<article class="ab-card" style="--qc:${M.c}">
      <div class="ab-top"><span class="ab-id">ID · ${q.code}</span><span class="ab-mk">${q.p} · ${q.m} marks · ${q.w} words</span></div>
      <div class="ab-topic">${ic('target')}<span>${M.topic}</span></div>
      <p class="ab-q ${B.lang === 'hi' && q.hi ? 'hi' : ''}"><span>Q.</span>${B.lang === 'hi' && q.hi ? q.hi : q.t}</p>
      ${B.lang === 'hi' && !q.hi ? '<span class="ab-soon">हिन्दी संस्करण जल्द आ रहा है</span>' : ''}
      <div class="ab-acts"><button class="ab-rev ${open ? 'on' : ''}" data-act="abOpen:${q.id}">${open ? 'Hide answer' : 'Model answer'}${ic('chevd')}</button><button class="ab-ev" data-act="mainsWith:${q.id}">Evaluate my answer ${ic('arrow')}</button></div>
      ${open ? `<div class="ab-model">${q.fw ? q.fw.map((f, i) => `<div class="ab-fw"><span>${i + 1}</span><div><b>${f[0]}</b><p>${f[1]}</p></div></div>`).join('') : `<div class="ab-html">${MODEL}</div>`}
        <div class="ab-mf"><span>${ic('spark')}Framework by PrepAssist faculty</span><button data-act="toast:Saved to your notes">${ic('bookmark')}Save</button></div></div>` : ''}
    </article>`; }).join('')}
  </div>` }

{ title: 'Syllabus Matrix', html: `<div class="me-page tlp">
    ${tHero('syllabus', 'The whole syllabus, <em>mapped</em>', 'Every concept, with how much of its question bank you’ve attempted.', '', `<div class="sy-ring"><svg viewBox="0 0 96 96">${ring(40, qa / qt, 8, '#FFD27A', 'rgba(255,255,255,.18)')}</svg><div><b>${(qa / qt * 100).toFixed(1)}%</b><span>${qa.toLocaleString('en-IN')} / ${qt.toLocaleString('en-IN')} questions</span></div></div>`)}
    <div class="sy-kpi">${[['All', all.length, 'All topics', '#14161C'], ['cov', cnt.cov, 'Covered', '#2F8A4A'], ['pen', cnt.pen, 'In progress', '#E8890C'], ['na', cnt.na, 'Not started', '#7A8494']].map(([k, v, l, c]) => `<button class="${Y.st === k ? 'on' : ''}" style="--kc:${c}" data-act="sySt:${k}"><b>${v}</b><span>${l}</span></button>`).join('')}</div>
    <div class="cx-fbar sy"><label class="sy-search">${ic('search')}<input id="syQ" value="${Y.q}" placeholder="Search topics — basic structure, inflation…" oninput="sySearch(this.value)" autocomplete="off"></label>
      <button class="cx-fbtn ${Y.p !== 'All' ? 'on' : ''}" data-act="syFilter" aria-label="Filter by paper">${ic('filter')}${Y.p !== 'All' ? '<i></i>' : ''}</button></div>
    ${Y.p !== 'All' ? `<div class="cx-active"><span>Showing</span><button data-act="syP:All" style="--g:${GSC[Y.p]}">${Y.p.toUpperCase().replace('GS', 'GS ')} ${ic('close')}</button></div>` : ''}
    <div id="syList">${groups.length ? groups.map(({ g, gi, t }) => { const ga = g.t.reduce((s, [n]) => s + (S.sylDone[n] || 0), 0), gt = g.t.reduce((s, x) => s + x[1], 0), open = Y.open[gi] || q; return `<section class="sy-grp ${open ? 'open' : ''}" style="--gc:${SUBJ[g.s] ? SUBJ[g.s].hex : '#C8622B'}">
      <button class="sy-gh" data-act="syOpen:${gi}"><span class="sy-gi">${ic('chevd')}</span><div><small>${g.p.toUpperCase().replace('GS', 'GS ')} · ${SUBJ[g.s] ? SUBJ[g.s].n : 'Ethics'}</small><b>#${g.g}</b><span class="sy-gb"><i style="width:${Math.max(1.5, ga / gt * 100)}%"></i></span></div><em>${ga}/${gt.toLocaleString('en-IN')}</em></button>
      ${open ? `<div class="sy-ts">${t.map(x => `<button class="sy-t s-${sylStatus(x)}" data-act="syTopic:${x.n.replace(/"/g, '')}"><i></i><span>${x.n}</span><em>${x.a}/${x.c}</em></button>`).join('')}</div>` : ''}
    </section>`; }).join('') : `<div class="cx-empty"><b>No topics match</b><p>Try a different word or clear your filters.</p><button data-act="syReset">Clear filters</button></div>`}</div>
  </div>` }

{ title: 'Saved Articles', noAsk: true, mount: liftFloat, html: `<div class="me-page tlp sv">
    ${tHero('saved', 'Your reading list', `${n} saved · ${arts.reduce((x, a) => x + a.min, 0)} min of reading`, tStat(arts.length, 'from Current') + tStat(L.length, 'web links'))}
    <div class="sv-tip">${ic('share')}<p>Tap <b>+</b> to paste a link. On iPhone, use Share → Copy Link, then paste it here. A Share extension is coming soon.</p></div>
    ${n ? `${arts.map(a => `<article class="sv-card" data-act="article:${a.id}"><span class="sv-src">${srcMg(a.src)}</span><div><small>${a.src} · ${a.gs} · ${a.min} min</small><b>${a.t}</b></div><button class="sv-rm" data-act="svRm:${a.id}" aria-label="Remove">${ic('bookmark')}</button></article>`).join('')}
      ${L.map((l, i) => `<article class="sv-card"><span class="sv-src"><span class="cx-mg" style="--m:#475467">${ic('link')}</span></span><div><small>${l.dom} · added ${l.d}</small><b>${l.t}</b></div><button class="sv-rm" data-act="svRmL:${i}" aria-label="Remove">${ic('close')}</button></article>`).join('')}`
    : `<section class="py-empty"><svg viewBox="0 0 120 96" aria-hidden="true"><circle cx="60" cy="48" r="40" fill="#FDECEC"/><path d="M46 28h28v42l-14-10-14 10Z" fill="#fff" stroke="#B42318" stroke-width="3" stroke-linejoin="round"/></svg><b>No saved articles yet</b><p>Bookmark stories in Current, or paste a link from any app.</p><button class="py-cta" data-act="tab:current">${ic('current')}Open today’s edition</button></section>`}
