  </div>` }

{ title: 'Upload to Cloud', html: `<div class="me-page tlp">
    ${tHero('upload', 'Feed your <em>vault</em>', 'Drop PDFs, docs or images — tag them once and every AI tool can read them.', tStat('100 MB', 'max file') + tStat('8', 'formats') + tStat(`${vaultMB().toFixed(0)} MB`, 'used'))}
    ${U.file ? `<section class="up2-stage"><div class="tq-file"><span class="tq-pdf" style="background:${U.file.k === 'JPG' ? '#0E9A8A' : '#E5484D'}">${U.file.k}</span><div><b>${U.file.n}</b><small>${U.file.sz} · ready to upload</small></div><button class="tq-x" data-act="upClear" aria-label="Remove">${ic('close')}</button></div>
        <h6 class="tl-k">Folder</h6><div class="ch2 wrap">${FOLDERS.map(([f, c]) => `<button class="${U.folder === f ? 'on' : ''}" style="--g:${c}" data-act="upFolder:${f}">${f}</button>`).join('')}</div>
        <h6 class="tl-k">Hashtags</h6><div class="up2-tags">${U.tags.map((t, i) => `<span>${t}<button data-act="upTagRm:${i}" aria-label="Remove tag">${ic('close')}</button></span>`).join('')}<input id="upTag" placeholder="#add-tag" onkeydown="if(event.key==='Enter'){event.preventDefault();upTagAdd(this.value)}"></div>
        ${U.prog >= 0 ? `<div class="up2-prog"><div><i style="width:${U.prog}%"></i></div><span>${U.prog < 100 ? 'Uploading… ' + U.prog + '%' : 'Uploaded · indexing for AI'}</span></div>` : ''}
        <button class="tl-cta" data-act="upGo" ${U.prog >= 0 ? 'disabled' : ''}>${ic('upload')}Upload to vault</button></section>`
    : `<button class="tl-drop lg" data-act="upPick:pdf"><span>${ic('upload')}</span><b>Stage a resource</b><small>PDF, DOCX, TXT, MD, PNG, JPG, WEBP · up to 100 MB</small></button>
      <div class="up2-src"><button data-act="upPick:pdf">${ic('file')}<b>Browse files</b><small>From your phone</small></button><button data-act="upPick:img">${ic('image')}<b>Gallery</b><small>Photos & scans</small></button><button data-act="push:note:new">${ic('pen')}<b>Text note</b><small>Write it here</small></button></div>`}
    <h6 class="tl-k">Recently uploaded</h6>
    <div class="me-card">${DOCS.slice(0, 3).map(d => `<div class="me-row"><span class="me-ri" style="--c:${d.k === 'JPG' ? '#0E9A8A' : '#E5484D'}">${ic(d.k === 'JPG' ? 'image' : 'file')}</span><div><b>${d.t}</b><small>${d.m}</small></div></div>`).join('')}</div>
    <button class="tl-ghost" data-act="push:cloud">${ic('db')}Open Cloud Data Vault</button>
  </div>` }

{ title: name, html: `<div class="me-page tlp">
    <section class="fd-hero" style="--fc:${F[1]}"><span class="fd-ic">${ic('learn')}</span><div><small>Notebook</small><h1>${name}</h1><p>${list.length + 3} notes · last edited today</p></div></section>
