{ title: 'AI Mindmap', action: `<button class="act" data-act="toast:Mindmap saved">${ic('bookmark')}</button>`, html: `<div class="sec"><span class="eyebrow">Generated just now · 6 branches</span><h1 class="display" style="font-size:28px;margin:6px 0 14px">${t}</h1>
    <div class="mm"><svg viewBox="0 0 360 400" font-family="Inter,sans-serif">${pos.map((p, i) => `<path d="M180 200 C${(180 + p[0]) / 2} 200 ${(180 + p[0]) / 2} ${p[1]} ${p[0]} ${p[1]}" fill="none" stroke="${col[i]}" stroke-width="2" opacity=".55"/>`).join('')}
      <rect x="122" y="180" width="116" height="40" rx="10" fill="#0A97B8"/><text x="180" y="205" text-anchor="middle" font-size="11.5" font-weight="700" fill="#fff">${t.length > 18 ? t.slice(0, 17) + '…' : t}</text>
      ${pos.map((p, i) => `<g><rect x="${p[0] - 56}" y="${p[1] - 20}" width="112" height="40" rx="8" fill="#fff" stroke="${col[i]}" stroke-width="1.4"/><text x="${p[0]}" y="${p[1] - 3}" text-anchor="middle" font-size="11" font-weight="700" fill="#25272D">${br[i][0]}</text><text x="${p[0]}" y="${p[1] + 11}" text-anchor="middle" font-size="9" fill="${col[i]}">${br[i][1]}</text></g>`).join('')}</svg></div>
    <p style="font-size:12.5px;color:var(--muted);margin-top:10px">Each branch follows the UPSC answer frame. Ask the Mentor to expand any branch.</p>
    <div style="display:flex;gap:8px;margin-top:14px;flex-wrap:wrap"><button class="btn btn-ink btn-sm" data-act="quiz">${ic('test')}Quiz me on this</button><button class="btn btn-line btn-sm" data-act="mentor">${ic('spark')}Expand with Mentor</button></div></div>` }

{ title: 'Notes', noAsk: true, mount: liftFloat, html: `<div class="me-page tlp">
    ${lxHero('#6C5DD3', 'notes', 'Notes', 'Your notes, <em>in one place</em>', 'Your own notes, scanned pages and verified faculty compendiums — all searchable and ready for AI.', tStat(NOTES.length, 'my notes') + tStat(NOTESYS.length, 'compendiums') + tStat(48, 'this month'))}
    <div class="sg2"><button class="${H.tab === 'mine' ? 'on' : ''}" data-act="nhTab:mine">${ic('pen')}My notes</button><button class="${H.tab === 'fac' ? 'on' : ''}" data-act="nhTab:fac">${ic('spark')}Faculty notes</button></div>
    ${H.tab === 'mine' ? `
      <label class="sy-search" style="margin-top:12px">${ic('search')}<input value="${H.q}" placeholder="Search your notes…" oninput="nhSearch(this.value)" autocomplete="off"></label>
      <div class="ch2"><button class="${H.s === 'all' ? 'on' : ''}" data-act="nhS:all">All</button>${subs.map(s => `<button class="${H.s === s ? 'on' : ''}" style="--g:${SUBJ[s].hex}" data-act="nhS:${s}">${SUBJ[s].n}</button>`).join('')}</div>
      <button class="lx-scan nh" data-act="lxScanNote">${ic('camera')}<div><b>Scan handwritten notes</b><small>We’ll turn a photo into searchable text</small></div>${ic('arrow')}</button>
      <div class="nh-grid" id="nhGrid">${mine.map(n => `<button class="nh-card" style="--c:${SUBJ[n.s].hex}" data-act="push:note:${n.id}"><small>${SUBJ[n.s].n}</small><b>${n.t}</b><p>${n.b}</p><em>${ic('clock')}${n.when}</em></button>`).join('') || '<div class="cx-empty" style="grid-column:span 2"><b>No notes match</b><p>Try another word or subject.</p></div>'}
        <button class="nh-card new" data-act="push:note:new"><span>${ic('plus')}</span><b>New note</b></button></div>`
    : NOTESYS.map(n => `<article class="ns-card" style="--nc:${n.c}" data-act="push:note2:${n.id}"><div class="ns-tp"><span>${ic('learn')}${n.subj}</span><em>${n.tag}</em></div><b>${n.t}</b><div class="ns-ft"><small>${ic('clock')}${n.min} min read · ${n.date}</small><span>Read note ${ic('arrow')}</span></div></article>`).join('')}
    <button class="sv-fab" style="background:linear-gradient(140deg,#8A7BEA,#6C5DD3);box-shadow:0 16px 26px -12px rgba(108,93,211,.8)" data-act="push:note:new" aria-label="New note">${ic('plus')}</button>
  </div>` }

{ title: F[0], action: `<button class="act n2-sa ${n.star ? 'on' : ''}" data-act="ntStar:${id}" aria-label="Star">${ic('star')}</button>`, html: `<div class="me-page tlp n2" style="--fc:${F[1]}">
